  gallica: [0, ['eiffel', 'dome'], 'none old trees river'], albion: [0, ['clock', 'wheel', 'towerbridge'], 'none old trees river mist'], mitropa: [0, ['tower', 'brandenburg'], 'none blocks trees river'], benelux: [0, ['canalhouses', 'windmill'], 'none old trees river'],
  baltovi: [0, ['polyhedron', 'spire'], 'none blocks pines river snowground'], carpodav: [0, ['goldendomes', 'onion'], 'hills old trees river'], scandor: [0, ['cityhall', 'spire'], 'hills colorful pines sea'], iberico: [0, ['alcala', 'dome'], 'hills old trees none'],
  alpomare: [0, ['colosseum', 'dome'], 'hills old trees river'], isgarde: [0, ['hallgrim', 'volcano'], 'snowpeaks colorful bare sea aurora snowground'], balka: [0, ['acropolis', 'temple'], 'hills adobe trees sea'],
  australis: [0, ['sails', 'harbourbridge'], 'none modern trees sea cranes'], avaiki: [0, ['lighthouse', 'volcano', 'palms'], 'volcanoes colorful palms sea'], aotea: [0, ['tower', 'volcano'], 'volcanoes mix trees sea'], kalimai: [0, ['stilts', 'palms'], 'hills stilts palms sea mist'],
  andina: [0, ['obelisk', 'dome'], 'none mix trees river'], amazonia: [0, ['christ', 'sugarloaf'], 'mountains modern palms sea'], aymaro: [0, ['twinspires', 'stepped'], 'mountains adobe cacti none dust'], polaris: [0, ['tower', 'skyscrapers'], 'none modern pines river snowground aurora'],
  atlante: [0, ['empire', 'statue', 'skyscrapers'], 'none modern bare sea cranes'], tropicana: [0, ['monserrate', 'dome'], 'mountains colorful trees none mist'], pacifica: [0, ['volcano', 'dome'], 'volcanoes colorful jungle none mist'], caribana: [0, ['dome', 'palms'], 'none colorful palms sea'],
  centro: [0, ['twinspires', 'volcano'], 'hills adobe trees none'], meso: [0, ['angel', 'stepped'], 'volcanoes adobe cacti none dust'], antille: [0, ['lighthouse', 'fort'], 'hills colorful palms sea'],
