  koryo: [0, ['tower', 'palacegate'], 'mountains mix pines river'], bengal: [0, ['arch', 'taj'], 'none adobe trees none dust'], banda: [0, ['monas', 'skyscrapers'], 'volcanoes modern palms sea mist'], khora: [0, ['azadi', 'tower'], 'snowpeaks blocks cacti none dust'],
  levant: [0, ['mosque', 'palms'], 'dunes adobe palms river dust'], yamato: [0, ['fuji', 'tokyotower'], 'volcanoes modern trees river'], turkestan: [0, ['tower', 'bluedome'], 'snowpeaks blocks cacti none dust'], sunda: [0, ['baroque', 'volcano'], 'volcanoes colorful palms sea mist'],
