  onion: (x, y, s, P) => `<g transform="translate(${x} ${y}) scale(${s})">${[[-46, 60, .8], [0, 100, 1.2], [48, 70, .9]].map(([dx, h, k]) => `<rect x="${dx - 14 * k}" y="${-h}" width="${28 * k}" height="${h}" fill="${P.light}"/><path d="M${dx - 20 * k},${-h} Q${dx - 26 * k},${-h - 44 * k} ${dx},${-h - 76 * k} Q${dx + 26 * k},${-h - 44 * k} ${dx + 20 * k},${-h} Z" fill="${P.accent}"/><rect x="${dx - 1.2}" y="${-h - 98 * k}" width="2.4" height="24" fill="${P.sun}"/>`).join('')}</g>`,
  pyramid: (x, y, s, P) => `<g transform="translate(${x} ${y}) scale(${s})"><polygon points="-110,0 0,-130 110,0" fill="${P.light}"/><polygon points="0,-130 110,0 20,0" fill="${P.rock}"/><polygon points="70,0 140,-62 210,0" fill="${P.far}"/><polygon points="140,-62 210,0 160,0" fill="${P.rock}" opacity=".8"/></g>`,
  pagoda: (x, y, s, P) => `<g transform="translate(${x} ${y}) scale(${s})">${[0, 1, 2, 3, 4].map(i => { const w = 78 - i * 11, yy = -i * 38; return `<rect x="${-w / 2 + 6}" y="${yy - 30}" width="${w - 12}" height="30" fill="${P.light}"/><path d="M${-w / 2 - 10},${yy - 28} Q0,${yy - 46} ${w / 2 + 10},${yy - 28} L${w / 2},${yy - 22} L${-w / 2},${yy - 22} Z" fill="${P.accent}"/>`; }).join('')}<rect x="-1.5" y="-230" width="3" height="40" fill="${P.dark}"/></g>`,
  sails: (x, y, s, P) => `<g transform="translate(${x} ${y}) scale(${s})"><rect x="-90" y="-12" width="190" height="12" fill="${P.mid}"/>${[[-70, 70, 100], [-20, 80, 120], [30, 62, 90], [70, 48, 66]].map(([dx, w, h]) => `<path d="M${dx - w / 2},-12 Q${dx - w / 2},${-h} ${dx + w / 2},-12 Z" fill="${P.light}"/><path d="M${dx},-12 Q${dx - w / 4},${-h * .7} ${dx + w / 2},-12 Z" fill="${P.far}" opacity=".7"/>`).join('')}</g>`,
  skyscrapers: (x, y, s, P, r) => `<g transform="translate(${x} ${y}) scale(${s})">${[-80, -40, 0, 40, 80].map((dx, i) => { const h = 120 + r() * 170, w = 26 + r() * 14; return `<rect x="${dx - w / 2}" y="${-h}" width="${w}" height="${h}" fill="${i % 2 ? P.mid : P.near}"/><rect x="${dx - w / 2}" y="${-h}" width="${w * .35}" height="${h}" fill="${P.light}" opacity=".35"/>${i === 2 ? `<rect x="${dx - 1.5}" y="${-h - 38}" width="3" height="40" fill="${P.dark}"/>` : ''}`; }).join('')}</g>`,
  mosque: (x, y, s, P) => `<g transform="translate(${x} ${y}) scale(${s})"><rect x="-60" y="-60" width="120" height="60" fill="${P.light}"/><path d="M-44,-60 A44,52 0 0 1 44,-60 Z" fill="${P.accent}"/><rect x="-1.5" y="-128" width="3" height="22" fill="${P.sun}"/>${[-78, 78].map(dx => `<rect x="${dx - 7}" y="-170" width="14" height="170" fill="${P.light}"/><polygon points="${dx - 9},-170 ${dx},-205 ${dx + 9},-170" fill="${P.accent}"/>`).join('')}</g>`,
  colosseum: (x, y, s, P) => `<g transform="translate(${x} ${y}) scale(${s})"><path d="M-120,0 L-120,-70 Q0,-95 120,-70 L120,0 Z" fill="${P.light}"/>${[0, 1, 2].map(r => [...Array(11)].map((_, i) => `<path d="M${-108 + i * 21},${-14 - r * 20} v-8 a5,5 0 0 1 10,0 v8 z" fill="${P.dark}" opacity=".55"/>`).join('')).join('')}</g>`,
  temple: (x, y, s, P) => `<g transform="translate(${x} ${y}) scale(${s})"><polygon points="-90,-82 0,-122 90,-82" fill="${P.light}"/><rect x="-90" y="-82" width="180" height="8" fill="${P.mid}"/>${[...Array(7)].map((_, i) => `<rect x="${-80 + i * 26}" y="-74" width="10" height="64" fill="${P.light}"/>`).join('')}<rect x="-100" y="-10" width="200" height="10" fill="${P.mid}"/></g>`,
  mountain: (x, y, s, P) => `<g transform="translate(${x} ${y}) scale(${s})"><polygon points="-150,0 -20,-190 130,0" fill="${P.rock}"/><polygon points="-20,-190 130,0 30,0" fill="${P.rockd}"/><g transform="translate(-20 -192)"><rect x="-2" y="-44" width="4" height="44" fill="${P.light}"/><rect x="-22" y="-34" width="44" height="4" fill="${P.light}"/></g></g>`,
  tablemount: (x, y, s, P) => `<g transform="translate(${x} ${y}) scale(${s})"><polygon points="-220,0 -190,-110 -150,-124 130,-124 180,-100 230,0" fill="${P.rock}"/><polygon points="130,-124 180,-100 230,0 120,0" fill="${P.rockd}"/><ellipse cx="-20" cy="-134" rx="150" ry="10" fill="${P.light}" opacity=".7"/></g>`,
  volcano: (x, y, s, P) => `<g transform="translate(${x} ${y}) scale(${s})"><polygon points="-150,0 -30,-150 30,-150 150,0" fill="${P.rock}"/><polygon points="30,-150 150,0 50,0" fill="${P.rockd}"/><polygon points="-30,-150 30,-150 18,-162 -18,-162" fill="${P.light}"/><circle cx="14" cy="-190" r="14" fill="${P.light}" opacity=".6"/><circle cx="26" cy="-218" r="18" fill="${P.light}" opacity=".4"/></g>`,
  fuji: (x, y, s, P) => `<g transform="translate(${x} ${y}) scale(${s})"><polygon points="-200,0 -30,-170 30,-170 200,0" fill="${P.rock}"/><polygon points="-52,-136 -30,-170 30,-170 52,-136 24,-146 0,-130 -24,-146" fill="#fff" opacity=".9"/></g>`,
  stepped: (x, y, s, P) => `<g transform="translate(${x} ${y}) scale(${s})">${[0, 1, 2, 3, 4].map(i => `<rect x="${-110 + i * 18}" y="${-(i + 1) * 24}" width="${220 - i * 36}" height="24" fill="${i % 2 ? P.mid : P.light}"/>`).join('')}<rect x="-14" y="-142" width="28" height="22" fill="${P.accent}"/></g>`,
  wat: (x, y, s, P) => `<g transform="translate(${x} ${y}) scale(${s})">${[[-34, 120], [0, 175], [34, 120]].map(([dx, h]) => `<polygon points="${dx - 16},0 ${dx - 12},${-h * .55} ${dx},${-h} ${dx + 12},${-h * .55} ${dx + 16},0" fill="${P.accent}"/><rect x="${dx - 18}" y="-12" width="36" height="12" fill="${P.light}"/>`).join('')}</g>`,
