  arch: (x, y, s, P) => `<g transform="translate(${x} ${y}) scale(${s})"><rect x="-70" y="-100" width="140" height="100" fill="${P.accent}"/><path d="M-30,0 V-52 a30,30 0 0 1 60,0 V0 Z" fill="${P.sky2}"/><rect x="-76" y="-112" width="152" height="14" fill="${P.light}"/></g>`,
